// TH14 synthetic training aliases (see transcribe/th14/touhou-bullets.ecl).
// Native 0..23 -> modern 0..23; native 24..42 -> modern +1.
const TH14_NOTE_RED: int = 976; // native type38 -> modern 39; source etSprite(0,38,0) uses color 0.

// TH14 v1.00b st04mbs2::MBossB(entry prologue) + MBossB1; source lines 8-38 and 53-82.
// Route A: SHOTTYPE 0/2/4, midboss ECL st04mbs2. Source MBossB1 t0 ~= card192:
// 120 opening buffer + prologue wait(40)+wait(30). Source timer 1800 ends at MBossB2
// boundary; that entry does killAllAsync + etClear(640), reproduced by the clear below.
const TIME_LIMIT: int = 2494; // 120 buffer + 70 prologue + 1800 source + 500 tail + 4 startup
const SOURCE_LIMIT: int = 1800;
const OPENING_BUFFER: int = 120;

// Source etEx chain: ANIM a1 (birth stage omitted, retreat kept via sh_dist), then four
// ANGLE_ACCEL records a=40 with r=+0.016,+0.015,-0.015,0 and s=0.008*RANDF2 rad/frame,
// then GOTO record4 loops the r=0 segment (constant spin, no further speed change).
xformdef NOTE_MOTION(w1: angle, w2: angle, w3: angle, w4: angle) {
    set_ang_vel(w1);
    set_accel(0.016fx);
    wait(40);
    set_ang_vel(w2);
    set_accel(0.015fx);
    wait(40);
    set_ang_vel(w3);
    set_accel(-0.015fx);
    wait(40);
    set_ang_vel(w4);
    set_accel(0fx);
}

sub fire_volley() {
    // Source 90-114: etNew/etAim(3)/etSprite(38,0)/etCount(stack)/etAngle(RANDRAD,.032724924)
    // /etSpeed(.4,1)/etDist(32)/etOffset(12+U*32,-12+U*32)/etEx*6/etOn.
    sh_reset(0);                              // source etNew(0)
    sh_sprite(0, TH14_NOTE_RED, 0);           // source etSprite(0,38,0)
    sh_aim(0, 0);
    sh_ring(0, 1);                            // source etAim(0,3): fixed-direction full ring
    var n: int = 12;                          // source rank stack: E12/N24/H32/L48
    var rank: int = global(GVAR_RANK);
    if rank == 1 { n = 24; }
    if rank == 2 { n = 32; }
    if rank == 3 { n = 48; }
    var alpha: angle = rand(65536) as angle;  // source %RANDRAD (uniform full circle)
    var ux: fx = (rand(65536)-32768) as fx / 32768;
    var uy: fx = (rand(65536)-32768) as fx / 32768;
    sh_offset(0, 12fx+32fx*ux, -12fx+32fx*uy); // source etOffset(12+%RANDF2*32, -12+%RANDF2*32)
    // Source etEx s=0.008*%RANDF2 rad/frame; 0.008rad ~= 83 BAM/frame. One sample per record.
    var u: fx = (rand(65536)-32768) as fx / 32768;
    var w1: angle = ((u*83fx) as int) as angle;
    u = (rand(65536)-32768) as fx / 32768;
    var w2: angle = ((u*83fx) as int) as angle;
    u = (rand(65536)-32768) as fx / 32768;
    var w3: angle = ((u*83fx) as int) as angle;
    u = (rand(65536)-32768) as fx / 32768;
    var w4: angle = ((u*83fx) as int) as angle;
    sh_count(0, n, 1);                        // source etCount(0,N,1); M=1 keeps speed0
    sh_angle(0, alpha, 341bam);               // source etAngle(0,RANDRAD,0.032724924); step unused at M=1
    sh_speed(0, 0.4fx, 0fx);                  // source etSpeed(0,0.4,1.0)
    sh_dist(0, 30.4fx);                       // source etDist(32) minus ANIM retreat 4*0.4
    sh_xform(0, NOTE_MOTION(w1, w2, w3, w4));
    sh_fire(0);                               // source etOn(0)
}

async sub fire_loop() {
    // Source 84-118: 120 volleys, one per 40 frames; MBossB2 interrupt cancels this async.
    while $frame < self_int(1) {
        fire_volley();
        wait(40);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source MBossB prologue: movePos(160,-48), movePosTime(60,4,0,128), flagSet(2).
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(40);
    set_enemy_flag(ENEMY_NO_BODY, 0);         // source flagClear(2) after wait(40); dialog omitted
    // Source EffChargePoint3 only writes decorative ANM/sound; omitted with visual effects.
    wait(30);
    // Source MBossB1: timerReset + setInterrupt(0,0,1800,"MBossB2").
    // F0/I0 written after the async start, preserving source line order 61-63.
    set_self_int(2, $frame);
    set_self_int(1, $frame+SOURCE_LIMIT);
    spawn fire_loop();
    set_self_fx(2, 0.017453fx);               // source %F0 at 62
    set_self_int(3, 2);                       // source $I0 at 63
    var gap: int = 80;                        // source !E/!N/!H 80
    if global(GVAR_RANK) == 3 { gap = 20; }   // source !LO 20 (Lunatic only)
    // Source 65-80: wait(60), wait(rank gap), moveRand(60,4,0.4), wait(70), repeat.
    loop {
        card_wait(60);
        if $frame >= self_int(1) { break; }
        card_wait(gap);
        if $frame >= self_int(1) { break; }
        card_move_rand();
        card_wait(70);
        if $frame >= self_int(1) { break; }
    }
    // Source MBossB2 timeout entry: etClear(640) around the boss, velocity reset.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // source setHitbox(48,48): ordinary circle radius 48*0.5
    set_hurtbox(24fx); // source setHurtbox(48,48)
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(160fx, -48fx, 13000, 0, 0, 0, boss_main); // source movePos(160,-48)
    loop { wait(600); }
}

// TH14 v1.00b MBossB1 moveRand(60,4,0.4) under moveLimit(0,128,280,64).
// Position clamp x[-140,140], y[96,160]; direction inner zone x+-70, y[112,144].
// int0=next step, int1=source end frame; fx0/fx1=source unit direction.
// All source wait(n) inside this attack must use card_wait(n), in the same owner task.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.4fx*((60-k) as fx)/60fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately no normalization before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}
